using System;
using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

public class FishM1Wiring
{
    private const string LINE_MAT_PATH = "Assets/Art/Materials/Mat_Tackle_Line.mat";

    private static StringBuilder s_log = new StringBuilder();

    public static void Run()
    {
        s_log = new StringBuilder();

        Scene scene = loadScene();

        if (!scene.IsValid())
        {
            Debug.LogError("[FishM1Wiring] Fishing 场景未打开");
            return;
        }

        GameObject hook = Find("World/Hook");
        GameObject world = Find("World");
        GameObject cameraGo = Find("Main Camera");
        GameObject sceneRoot = Find("Fishing");
        Transform rodAnchor = FindT("World/Rod/LineAnchor");
        Transform hookAnchor = FindT("World/Hook/LightAnchor");

        Rarity("RarityTable", "Assets/Data/Config/RarityTable.asset", out UnityEngine.Object rarityTable);
        Rarity("HookConfig", "Assets/Data/Config/HookConfig.asset", out UnityEngine.Object hookConfig);
        Rarity("SessionConfig", "Assets/Data/Config/FishingSession_Island1.asset", out UnityEngine.Object sessionConfig);

        Transform fishRoot = ensureFishRoot(world);
        ensureComponent(hook, "Module.Fish.View.HookViewController, Assembly-CSharp");
        ensureComponent(hook, "Module.Fish.View.FishingLineView, Assembly-CSharp");
        Component line = ensureComponent(hook, "UnityEngine.LineRenderer, UnityEngine.CoreModule");
        ensureComponent(cameraGo, "Module.Fish.View.FishingCameraRig, Assembly-CSharp");

        setVec3(hook, "Module.Fish.View.HookViewController, Assembly-CSharp", "HoleAnchorPosition", new Vector3(0f, 0f, -1.5f));

        Component lineView = component(hook, "Module.Fish.View.FishingLineView, Assembly-CSharp");
        setRef(lineView, "RodAnchor", rodAnchor);
        setRef(lineView, "HookAnchor", hookAnchor);
        setRef(lineView, "HookConfigAsset", hookConfig);

        Material lineMaterial = ensureLineMaterial();
        if (line != null)
        {
            ((LineRenderer)line).sharedMaterial = lineMaterial;
            ((LineRenderer)line).positionCount = 2;
            EditorUtility.SetDirty(line);
        }

        Component rig = component(cameraGo, "Module.Fish.View.FishingCameraRig, Assembly-CSharp");
        setRef(rig, "Target", cameraGo.GetComponent<Camera>());
        setRef(rig, "FollowTarget", hook != null ? hook.transform : null);

        Component sceneView = sceneRoot != null ? sceneRoot.GetComponent("FishingScene") : null;
        setRef(sceneView, "RarityTableAsset", rarityTable);
        setRef(sceneView, "HookConfigAsset", hookConfig);
        setRef(sceneView, "SessionConfigAsset", sessionConfig);
        setRef(sceneView, "HookView", component(hook, "Module.Fish.View.HookViewController, Assembly-CSharp"));
        setRef(sceneView, "CameraRigView", rig);
        setRef(sceneView, "FishRootNode", fishRoot);

        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        AssetDatabase.SaveAssets();

        Debug.Log("[FishM1Wiring]\n" + s_log);
    }

    private static Scene loadScene()
    {
        for (int i = 0; i < SceneManager.sceneCount; i++)
        {
            Scene s = SceneManager.GetSceneAt(i);
            if (s.name == "Fishing" && s.isLoaded)
                return s;
        }

        return EditorSceneManager.OpenScene("Assets/Scenes/Fishing.unity", OpenSceneMode.Single);
    }

    private static GameObject Find(string path)
    {
        GameObject go = GameObject.Find(path);
        s_log.AppendLine((go == null ? "MISS  " : "OK    ") + path);
        return go;
    }

    private static Transform FindT(string path)
    {
        GameObject go = Find(path);
        return go != null ? go.transform : null;
    }

    private static void Rarity(string label, string path, out UnityEngine.Object asset)
    {
        asset = AssetDatabase.LoadAssetAtPath<UnityEngine.Object>(path);
        s_log.AppendLine((asset == null ? "MISS  " : "OK    ") + label + " -> " + (asset != null ? asset.GetType().Name : path));
    }

    private static Transform ensureFishRoot(GameObject world)
    {
        if (world == null)
            return null;

        Transform existing = world.transform.Find("FishRoot");

        if (existing != null)
        {
            s_log.AppendLine("KEEP  World/FishRoot");
            return existing;
        }

        GameObject created = new GameObject("FishRoot");
        created.transform.SetParent(world.transform, false);
        created.transform.localPosition = new Vector3(0f, 0f, -0.8f);
        s_log.AppendLine("ADD   World/FishRoot z=-0.8");
        return created.transform;
    }

    private static Component component(GameObject go, string typeName)
    {
        return go == null ? null : go.GetComponent(Type.GetType(typeName));
    }

    private static Component ensureComponent(GameObject go, string typeName)
    {
        if (go == null)
            return null;

        Type type = Type.GetType(typeName);

        if (type == null)
        {
            s_log.AppendLine("BADTY " + typeName);
            return null;
        }

        Component existing = go.GetComponent(type);

        if (existing != null)
        {
            s_log.AppendLine("KEEP  " + type.Name);
            return existing;
        }

        s_log.AppendLine("ADD   " + type.Name + " -> " + go.name);
        return go.AddComponent(type);
    }

    private static void setRef(Component target, string property, UnityEngine.Object value)
    {
        if (target == null)
        {
            s_log.AppendLine("NULGT " + property);
            return;
        }

        SerializedObject serialized = new SerializedObject(target);
        SerializedProperty found = serialized.FindProperty(property);

        if (found == null)
        {
            s_log.AppendLine("NOPRP " + target.GetType().Name + "." + property);
            return;
        }

        found.objectReferenceValue = value;
        serialized.ApplyModifiedPropertiesWithoutUndo();
        EditorUtility.SetDirty(target);
        s_log.AppendLine("SET   " + target.GetType().Name + "." + property + " = " + (value != null ? value.name : "null"));
    }

    private static void setVec3(GameObject go, string typeName, string property, Vector3 value)
    {
        Component target = component(go, typeName);

        if (target == null)
        {
            s_log.AppendLine("NULGT " + property);
            return;
        }

        SerializedObject serialized = new SerializedObject(target);
        SerializedProperty found = serialized.FindProperty(property);

        if (found == null)
        {
            s_log.AppendLine("NOPRP " + property);
            return;
        }

        found.vector3Value = value;
        serialized.ApplyModifiedPropertiesWithoutUndo();
        EditorUtility.SetDirty(target);
        s_log.AppendLine("SET   " + property + " = " + value);
    }

    private static Material ensureLineMaterial()
    {
        Material existing = AssetDatabase.LoadAssetAtPath<Material>(LINE_MAT_PATH);

        if (existing != null)
        {
            s_log.AppendLine("KEEP  " + LINE_MAT_PATH);
            return existing;
        }

        Shader shader = Shader.Find("Universal Render Pipeline/Unlit");

        if (shader == null)
        {
            s_log.AppendLine("NOSHD URP/Unlit");
            return null;
        }

        Material created = new Material(shader);
        created.SetColor("_BaseColor", new Color(0.09f, 0.11f, 0.13f, 1f));
        AssetDatabase.CreateAsset(created, LINE_MAT_PATH);
        s_log.AppendLine("ADD   " + LINE_MAT_PATH);
        return created;
    }
}
